/**
 * Flags open invoices that are past due as Overdue and records a run summary.
 *
 * Database.Stateful keeps the running totals across every chunk of the job,
 * so the totals are correct whatever batch size is used.
 */
public class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    private static final String JOB_NAME = 'OverdueInvoiceBatch';
    private static final String STATUS_OPEN = 'Open';
    private static final String STATUS_OVERDUE = 'Overdue';

    // Running totals for the whole job (Stateful keeps them between chunks).
    @TestVisible
    private Integer recordsUpdated = 0;
    @TestVisible
    private Integer recordsFailed = 0;
    @TestVisible
    private Decimal overdueAmount = 0;

    public OverdueInvoiceBatch() {
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = :STATUS_OPEN
            AND Due_Date__c < :Date.today()
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        // Build fresh sObjects so the caller's records are never mutated and every
        // field the validation rule / totals rely on is carried over explicitly.
        List<FB_Invoice__c> invoicesToUpdate = new List<FB_Invoice__c>();
        for (SObject record : scope) {
            FB_Invoice__c source = (FB_Invoice__c) record;
            invoicesToUpdate.add(
                new FB_Invoice__c(
                    Id = source.Id,
                    Status__c = STATUS_OVERDUE,
                    Due_Date__c = source.Due_Date__c,
                    Amount__c = source.Amount__c,
                    Customer_Email__c = source.Customer_Email__c
                )
            );
        }

        // Partial success: one failing record (e.g. blank Customer_Email__c) must not
        // stop the rest of the chunk from being saved.
        List<Database.SaveResult> results = Database.update(invoicesToUpdate, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                recordsUpdated++;
                if (invoicesToUpdate[i].Amount__c != null) {
                    overdueAmount += invoicesToUpdate[i].Amount__c;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        insert new FB_Job_Summary__c(
            Job_Name__c = JOB_NAME,
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
    }
}
