/**
 * Handler for ContactTrigger.
 *
 * Bulk-safe by construction: one SOQL query per trigger context and at most one
 * DML statement per context. An insert of up to 200 contacts therefore costs
 * 2 SOQL queries (1 before + 1 after) and 1 DML statement (the account update).
 *
 * Declared without sharing because trigger code runs in system mode and the
 * original trigger defaulted fields and updated accounts regardless of the
 * running user's sharing access.
 */
public without sharing class ContactTriggerHandler {

    private ContactTriggerHandler() {
    }

    public static void beforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    public static void afterInsert(List<Contact> newContacts) {
        setAccountPhoneFromFirstContact(newContacts);
    }

    /**
     * Copies Account.BillingCountry to Contact.MailingCountry whenever the contact
     * value is blank, and on insert only also copies Account.AccountSource to
     * Contact.LeadSource whenever the contact value is blank.
     */
    private static void applyAccountDefaults(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId != null) {
                accountIds.add(newContact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(newContact.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(newContact.MailingCountry)) {
                newContact.MailingCountry = account.BillingCountry;
            }
            if (isInsert == true && String.isBlank(newContact.LeadSource)) {
                newContact.LeadSource = account.AccountSource;
            }
        }
    }

    /**
     * Sets Account.Phone from the phone of the first contact (in trigger order) of
     * that account that carries one, but only while the account's phone is blank.
     * Each account is updated at most once, with a single DML statement.
     */
    private static void setAccountPhoneFromFirstContact(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId != null && String.isNotBlank(newContact.Phone)) {
                accountIds.add(newContact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null
                || String.isBlank(newContact.Phone)
                || accountsToUpdate.containsKey(newContact.AccountId)) {
                continue;
            }

            Account account = accountsById.get(newContact.AccountId);
            if (account == null || String.isNotBlank(account.Phone)) {
                continue;
            }

            account.Phone = newContact.Phone;
            accountsToUpdate.put(newContact.AccountId, account);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
