/**
 * Live FX rate client for the provider configured on the Named Credential
 * `FB_Exchange_Rates`.
 *
 * Uses: GET callout:FB_Exchange_Rates/v1/latest?base=EUR&symbols=USD,GBP
 */
public class ExchangeRateClient {

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer STATUS_OK = 200;
    private static final Integer STATUS_SERVICE_UNAVAILABLE = 503;
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    /** Thrown when input is invalid, the service fails, or the payload cannot be used. */
    public class ExchangeRateException extends Exception {
    }

    /**
     * Returns the latest rate of every requested quote currency against the base currency.
     *
     * @param baseCurrency    Base currency code, e.g. 'EUR'.
     * @param quoteCurrencies Quote currency codes to resolve, e.g. {'USD', 'GBP'}.
     * @return Map keyed by every normalised quote currency code with its rate.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Normalise and validate all input before any callout is made.
        String base = normaliseCode(baseCurrency, 'Base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        Set<String> quotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            quotes.add(normaliseCode(quoteCurrency, 'Quote currency'));
        }

        String endpoint = buildEndpoint(base, quotes);

        HttpResponse response = sendRequest(endpoint);
        if (response.getStatusCode() == STATUS_SERVICE_UNAVAILABLE) {
            // Exactly one retry, with an identical request.
            response = sendRequest(endpoint);
        }

        if (response.getStatusCode() != STATUS_OK) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + response.getStatusCode() + '.'
            );
        }

        Map<String, Object> returnedRates = parseRates(response.getBody());

        Map<String, Decimal> rates = new Map<String, Decimal>();
        for (String quote : quotes) {
            Object returnedRate = returnedRates.get(quote);
            if (returnedRate == null) {
                throw new ExchangeRateException('No rate returned for ' + quote + '.');
            }
            rates.put(quote, toRate(returnedRate, quote));
        }
        return rates;
    }

    private static String buildEndpoint(String base, Set<String> quotes) {
        // Codes are validated as [A-Z]{3}, so the query string needs no encoding.
        return ENDPOINT + '?base=' + base + '&symbols=' + String.join(new List<String>(quotes), ',');
    }

    private static HttpResponse sendRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        return http.send(request);
    }

    private static String normaliseCode(String code, String label) {
        if (code == null) {
            throw new ExchangeRateException(label + ' must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (!CURRENCY_CODE_PATTERN.matcher(normalised).matches()) {
            throw new ExchangeRateException(
                label + ' must be exactly three letters A-Z, found: "' + code.trim() + '".'
            );
        }
        return normalised;
    }

    private static Map<String, Object> parseRates(String body) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }

        Map<String, Object> rootMap;
        try {
            rootMap = (Map<String, Object>) root;
        } catch (TypeException e) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }
        if (rootMap == null) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }

        Map<String, Object> returnedRates;
        try {
            returnedRates = (Map<String, Object>) rootMap.get('rates');
        } catch (TypeException e) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }
        if (returnedRates == null) {
            throw new ExchangeRateException('Unable to parse the exchange rate response body.');
        }

        // Key the payload by normalised code; extra rates are simply ignored.
        Map<String, Object> ratesByCode = new Map<String, Object>();
        for (String key : returnedRates.keySet()) {
            ratesByCode.put(key.trim().toUpperCase(), returnedRates.get(key));
        }
        return ratesByCode;
    }

    private static Decimal toRate(Object rawRate, String currencyCode) {
        if (rawRate instanceof Decimal) {
            return (Decimal) rawRate;
        }
        if (rawRate instanceof Integer || rawRate instanceof Long || rawRate instanceof Double) {
            try {
                return Decimal.valueOf(String.valueOf(rawRate));
            } catch (Exception e) {
                throw new ExchangeRateException('Unable to parse the rate returned for ' + currencyCode + '.');
            }
        }
        throw new ExchangeRateException('Unable to parse the rate returned for ' + currencyCode + '.');
    }
}
