/**
 * Service for grouping Contact records by their email domain.
 *
 * The class is declared with sharing so that all queries run in the context of
 * the running user and only return records that user is allowed to see.
 */
public with sharing class ContactDomainService {

    /**
     * Groups the contacts of the given accounts by the domain part of their
     * email address, lower-cased (e.g. 'Jane@Example.COM' maps to the key
     * 'example.com'). Contacts without a usable email address are omitted.
     *
     * @param accountIds Ids of the accounts whose contacts should be grouped.
     * @return Contacts keyed by lower-cased email domain; never null. An empty
     *         map is returned for a null or empty input set.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Single, sharing-aware, bulk query: no per-record SOQL inside loops.
        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ]) {
            String domain = extractEmailDomain(contactRecord.Email);
            if (domain == null) {
                continue;
            }

            List<Contact> domainContacts = contactsByDomain.get(domain);
            if (domainContacts == null) {
                domainContacts = new List<Contact>();
                contactsByDomain.put(domain, domainContacts);
            }
            domainContacts.add(contactRecord);
        }

        return contactsByDomain;
    }

    /**
     * Returns the lower-cased domain part of an email address, or null when no
     * valid domain can be determined (blank value or no local/domain parts).
     */
    private static String extractEmailDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        String value = email.trim();
        Integer atIndex = value.lastIndexOf('@');

        // No '@', or missing local part / domain part.
        if (atIndex <= 0 || atIndex == value.length() - 1) {
            return null;
        }

        return value.substring(atIndex + 1).toLowerCase();
    }
}
