/**
 * @description Flow invocable action ("Find Contact by Email") that resolves an email
 *              address to the earliest-created Contact that matches it.
 *
 *              Bulk-safe: the action is designed for a single Flow interview batch
 *              (up to 200 requests) and uses exactly one SOQL query for the whole batch.
 *              The class is declared `with sharing` so results respect the running user's
 *              record visibility.
 */
public with sharing class ContactLookupAction {

    /**
     * @description Invocable entry point for Flow.
     * @param requests One Request per Flow interview, in batch order.
     * @return Exactly one Result per Request, in the same order as `requests`.
     */
    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds the earliest-created Contact matching the supplied email address (case-insensitive).'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // 1) Normalize (trim + lowercase) every requested email and collect the distinct,
        //    non-blank values so a single query can serve the whole batch.
        Set<String> lookupEmails = new Set<String>();
        for (Request req : requests) {
            String normalized = normalizeEmail(req == null ? null : req.email);
            if (normalized != null) {
                lookupEmails.add(normalized);
            }
        }

        // 2) One SOQL query for the entire batch. `with sharing` enforces the running
        //    user's sharing. Ordering by CreatedDate lets us keep the earliest match per
        //    email with a simple "first one wins" pass.
        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!lookupEmails.isEmpty()) {
            for (Contact candidate : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :lookupEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalizeEmail(candidate.Email);
                if (key != null && !earliestContactByEmail.containsKey(key)) {
                    earliestContactByEmail.put(key, candidate);
                }
            }
        }

        // 3) Emit exactly one Result per Request, preserving request order.
        for (Request req : requests) {
            String normalized = normalizeEmail(req == null ? null : req.email);
            Contact match = normalized == null ? null : earliestContactByEmail.get(normalized);
            results.add(toResult(match));
        }

        return results;
    }

    /**
     * @description Normalizes an email for comparison: blank/null => null, otherwise
     *              trimmed and lower-cased so matching is case-insensitive and
     *              whitespace-tolerant.
     */
    private static String normalizeEmail(String value) {
        if (String.isBlank(value)) {
            return null;
        }
        return value.trim().toLowerCase();
    }

    /**
     * @description Builds the Flow output for a single request. `found` is always set
     *              (never left null) and `contactId` is null when nothing matched.
     */
    private static Result toResult(Contact match) {
        Result result = new Result();
        result.found = match != null;
        result.contactId = match != null ? match.Id : null;
        return result;
    }

    /** @description Input for a single Flow interview. */
    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address to search for. Matching is case-insensitive and ignores surrounding spaces.'
            required=true
        )
        public String email;
    }

    /** @description Output for a single Flow interview. */
    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the earliest-created matching Contact, or null when no match was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True when a matching Contact was found, otherwise false.'
        )
        public Boolean found;
    }
}
