public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static OrderPayloadParser.Order parse(String body) {
        try {
            return parsePayload(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Unable to parse order payload.');
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        String number = order == null ? null : order.orderNumber;
        Integer lineCount = (order == null || order.lines == null)
            ? 0
            : order.lines.size();
        Decimal total = (order == null || order.total == null)
            ? Decimal.valueOf('0')
            : order.total;

        JSONGenerator generator = JSON.createGenerator(false);
        generator.writeStartObject();

        if (number == null) {
            generator.writeNullField('number');
        } else {
            generator.writeStringField('number', number);
        }

        generator.writeStringField('status', 'RECEIVED');
        generator.writeNumberField('lineCount', lineCount);
        generator.writeNumberField('total', total);
        generator.writeEndObject();

        return generator.getAsString();
    }

    private static Order parsePayload(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is required.');
        }

        Object rootObject;
        try {
            rootObject = JSON.deserializeUntyped(body.trim());
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON.');
        }

        Map<String, Object> root;
        try {
            root = (Map<String, Object>) rootObject;
        } catch (Exception e) {
            throw new PayloadException('JSON payload must be an object.');
        }

        if (root == null) {
            throw new PayloadException('JSON payload must be an object.');
        }

        Order order = new Order();
        order.orderNumber = asRequiredString(root.get('number'), 'number');
        order.orderDate = parseDate(root.get('date'));
        order.currencyCode = asOptionalString(root.get('currency'));

        Object customerValue = root.get('customer');
        if (customerValue != null) {
            try {
                Map<String, Object> customer = (Map<String, Object>) customerValue;
                order.customerEmail = asOptionalString(customer.get('email'));
            } catch (Exception e) {
                order.customerEmail = null;
            }
        }

        order.lines = new List<Line>();
        Object linesValue = root.get('lines');
        if (linesValue != null) {
            List<Object> rawLines;
            try {
                rawLines = (List<Object>) linesValue;
            } catch (Exception e) {
                throw new PayloadException('lines must be an array.');
            }

            for (Object rawLine : rawLines) {
                Map<String, Object> rawLineMap;
                try {
                    rawLineMap = (Map<String, Object>) rawLine;
                } catch (Exception e) {
                    throw new PayloadException('Each line must be an object.');
                }

                if (rawLineMap == null) {
                    throw new PayloadException('Each line must be an object.');
                }

                order.lines.add(parseLine(rawLineMap));
            }
        }

        order.total = Decimal.valueOf('0');
        for (Line line : order.lines) {
            order.total = order.total + line.lineTotal;
        }

        return order;
    }

    private static Line parseLine(Map<String, Object> rawLine) {
        if (rawLine == null) {
            throw new PayloadException('Each line must be an object.');
        }

        Line line = new Line();
        line.sku = asRequiredString(rawLine.get('sku'), 'sku');

        Object quantityValue = rawLine.get('quantity');
        if (quantityValue == null) {
            throw new PayloadException('Line quantity is required.');
        }

        Decimal quantityDecimal = asDecimal(quantityValue, 'quantity');
        if (quantityDecimal <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        line.quantity = toInteger(quantityDecimal, 'quantity');

        Object unitPriceValue = rawLine.get('unitPrice');
        if (unitPriceValue == null) {
            throw new PayloadException('Line unitPrice is required.');
        }

        line.unitPrice = asDecimal(unitPriceValue, 'unitPrice');
        if (line.unitPrice < 0) {
            throw new PayloadException('Line unitPrice must not be negative.');
        }

        Object discountValue = rawLine.get('discount');
        if (discountValue == null) {
            line.discount = Decimal.valueOf('0');
        } else {
            line.discount = asDecimal(discountValue, 'discount');
            if (line.discount < 0 || line.discount > 1) {
                throw new PayloadException('Line discount must be between 0 and 1.');
            }
        }

        try {
            Decimal rawLineTotal = line.quantity
                * line.unitPrice
                * (Decimal.valueOf('1') - line.discount);

            line.lineTotal = rawLineTotal.setScale(2, RoundingMode.HALF_UP);
        } catch (Exception e) {
            throw new PayloadException('Unable to calculate line total.');
        }

        return line;
    }

    private static Date parseDate(Object value) {
        if (value == null || !(value instanceof String)) {
            return null;
        }

        String dateText = ((String) value).trim();
        if (String.isBlank(dateText)) {
            return null;
        }

        try {
            return Date.valueOf(dateText);
        } catch (Exception e) {
            throw new PayloadException('date must be a valid ISO date (yyyy-MM-dd).');
        }
    }

    private static String asRequiredString(Object value, String fieldName) {
        if (value == null) {
            throw new PayloadException('Field ' + fieldName + ' is required.');
        }

        String text;
        if (value instanceof String) {
            text = (String) value;
        } else {
            text = String.valueOf(value);
        }

        text = text == null ? null : text.trim();
        if (String.isBlank(text)) {
            throw new PayloadException('Field ' + fieldName + ' must not be blank.');
        }

        return text;
    }

    private static String asOptionalString(Object value) {
        if (!(value instanceof String)) {
            return null;
        }

        String text = ((String) value).trim();
        return String.isBlank(text) ? null : text;
    }

    private static Decimal asDecimal(Object value, String fieldName) {
        if (value == null) {
            throw new PayloadException('Field ' + fieldName + ' is required.');
        }

        try {
            String text = String.valueOf(value).trim();
            if (String.isBlank(text)) {
                throw new PayloadException('Field ' + fieldName + ' must be numeric.');
            }
            return Decimal.valueOf(text);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Field ' + fieldName + ' must be numeric.');
        }
    }

    private static Integer toInteger(Decimal value, String fieldName) {
        try {
            Decimal wholeValue = value.setScale(0, RoundingMode.DOWN);
            if (value != wholeValue) {
                throw new PayloadException('Field ' + fieldName + ' must be a whole number.');
            }
            return value.intValue();
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Field ' + fieldName + ' must be a valid integer.');
        }
    }
