/**
 * Bulk-safe service used by the trade-show lead intake screen.
 *
 * Behaviour:
 *  - Valid leads are inserted even when other leads in the same call are invalid.
 *  - Exactly one DML statement is issued per call (partial-success insert).
 *  - LeadSource defaults to 'Web' when blank.
 *  - Duplicate emails inside one call are detected case-insensitively on the
 *    trimmed address; only the first occurrence reaches the database.
 *  - Row-level failures are reported per 0-based input index.
 *  - Sharing of the running user is enforced (with sharing).
 */
public with sharing class LeadImportService {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';
    private static final String DUPLICATE_EMAIL_PREFIX = 'Duplicate email in import: ';
    private static final String NULL_LEAD_ERROR = 'Lead cannot be null.';
    private static final String ERROR_SEPARATOR = '; ';

    /**
     * Imports the supplied leads, inserting every lead that can be inserted.
     *
     * @param leads Leads from the upload, in the order shown on screen.
     * @return Per-row import outcome; all members are non-null.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> inputIndexes = new List<Integer>();
        Set<String> emailsSeen = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead currentLead = leads[i];

            if (currentLead == null) {
                result.errorsByIndex.put(i, NULL_LEAD_ERROR);
                continue;
            }

            if (String.isBlank(currentLead.LeadSource)) {
                currentLead.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            String normalizedEmail = normalizeEmail(currentLead.Email);
            if (normalizedEmail != null) {
                if (emailsSeen.contains(normalizedEmail)) {
                    // Later occurrences are never sent to the database, even when
                    // the first occurrence ends up failing to insert.
                    result.errorsByIndex.put(i, DUPLICATE_EMAIL_PREFIX + normalizedEmail);
                    continue;
                }
                emailsSeen.add(normalizedEmail);
            }

            leadsToInsert.add(currentLead);
            inputIndexes.add(i);
        }

        if (leadsToInsert.isEmpty()) {
            return result;
        }

        // Single DML statement for the whole call; failed rows do not block valid rows.
        List<Database.SaveResult> saveResults = Database.insert(leadsToInsert, false);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult saveResult = saveResults[j];
            Integer inputIndex = inputIndexes[j];

            if (saveResult.isSuccess()) {
                result.insertedIds.add(saveResult.getId());
            } else {
                result.errorsByIndex.put(inputIndex, buildErrorMessage(saveResult));
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }

    /**
     * Normalizes an email address to its trimmed, lower-cased form.
     * Returns null for leads without an email; such leads are never duplicates.
     */
    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }

    /** Joins every database error for a row with '; '. */
    private static String buildErrorMessage(Database.SaveResult saveResult) {
        List<String> messages = new List<String>();
        for (Database.Error dbError : saveResult.getErrors()) {
            messages.add(dbError.getMessage());
        }
        return String.join(messages, ERROR_SEPARATOR);
    }

    /** Outcome of an import call; every member is initialized and never null. */
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }
}
