/**
 * PicklistService
 *
 * Describes the active values of any picklist or multi-select picklist field at
 * runtime. Only schema describe calls are used (no SOQL, no DML, no callouts),
 * so the service is safe to call from triggers, batchable/queueable code,
 * invocable methods and admin utilities.
 *
 * All failures surface as PicklistService.PicklistServiceException; no other
 * exception type is ever propagated to the caller.
 */
public with sharing class PicklistService {

    /**
     * One active picklist value as exposed to the caller.
     */
    public class Option {
        /** The API value that is stored on the record (for multi-select picklists the individual value). */
        public String value;

        /** The label displayed in the Salesforce UI. */
        public String label;

        /** True only for the value(s) configured as the field default. */
        public Boolean isDefault;
    }

    /**
     * The single exception type thrown by this service.
     */
    public class PicklistServiceException extends Exception {
    }

    /**
     * Returns the active values of a picklist or multi-select picklist field,
     * in the order the values are defined on the field. Inactive values are omitted.
     *
     * Object and field API names are case-insensitive and may belong to standard
     * or custom objects/fields.
     *
     * @param objectApiName API name of the object, e.g. 'account' or 'FB_Asset_Check__c'.
     * @param fieldApiName  API name of the picklist field, e.g. 'INDUSTRY' or 'Status__c'.
     * @return the active options in field definition order.
     * @throws PicklistServiceException when a name is null/blank, the object does not exist,
     *         the field does not exist on the object, or the field is not a (multi-)picklist.
     */
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            // --- Argument validation -------------------------------------------------
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name must not be null or blank.');
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name must not be null or blank.');
            }

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            // --- Object lookup (case-insensitive, standard or custom) ----------------
            Schema.SObjectType objectType = findObjectType(objectName);
            if (objectType == null) {
                throw new PicklistServiceException('Object "' + objectName + '" does not exist.');
            }

            // --- Field lookup (case-insensitive, standard or custom) -----------------
            Schema.DescribeFieldResult fieldDescribe = findFieldDescribe(objectType, fieldName);
            if (fieldDescribe == null) {
                throw new PicklistServiceException(
                    'Field "' + fieldName + '" does not exist on object "' + objectName + '".'
                );
            }

            // --- Type validation -----------------------------------------------------
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field "' + fieldName + '" on object "' + objectName +
                    '" is of type ' + fieldType + ', not a picklist or multi-select picklist.'
                );
            }

            // --- Collect active values in field definition order ---------------------
            List<PicklistService.Option> options = new List<PicklistService.Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry != null && entry.isActive()) {
                    PicklistService.Option option = new PicklistService.Option();
                    option.value = entry.getValue();
                    option.label = entry.getLabel();
                    // isDefaultValue() is true for the field default, and for each value
                    // that is part of the default of a multi-select picklist.
                    option.isDefault = entry.isDefaultValue();
                    options.add(option);
                }
            }
            return options;

        } catch (PicklistServiceException ex) {
            // Already the expected exception type - propagate unchanged.
            throw ex;
        } catch (Exception ex) {
            // Defensive: never leak NullPointerException or any other exception type.
            throw new PicklistServiceException(
                'Unexpected error while resolving picklist values for ' + objectApiName + '.' + fieldApiName +
                ': ' + ex.getMessage()
            );
        }
    }

    /**
     * Resolves an sObject type by API name, case-insensitively.
     * Returns null when the object does not exist.
     */
    private static Schema.SObjectType findObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        Schema.SObjectType objectType = globalDescribe.get(objectApiName);
        if (objectType != null) {
            return objectType;
        }

        for (String key : globalDescribe.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    /**
     * Resolves a field describe result by API name, case-insensitively.
     * Returns null when the field does not exist on the object.
     */
    private static Schema.DescribeFieldResult findFieldDescribe(Schema.SObjectType objectType, String fieldApiName) {
        Map<String, Schema.SObjectField> fields = objectType.getDescribe().fields.getMap();

        Schema.SObjectField field = fields.get(fieldApiName);
        if (field == null) {
            for (String key : fields.keySet()) {
                if (key != null && key.equalsIgnoreCase(fieldApiName)) {
                    field = fields.get(key);
                    break;
                }
            }
        }
        return (field == null) ? null : field.getDescribe();
    }
}
