/**
 * Processes FB_Shipment_Event__e events and marks the matching sales orders
 * as shipped.
 *
 * Runs without sharing because the events are raised by the warehouse
 * integration and must be applied to every matching order regardless of the
 * running user's record visibility (platform event triggers run as the
 * Automated Process user).
 *
 * Bulk-safe by design: one SOQL query and at most one DML statement per call,
 * no matter how many events arrive in the batch.
 */
public without sharing class ShipmentEventHandler {

    private static final String STATUS_SHIPPED = 'Shipped';
    private static final String STATUS_CANCELLED = 'Cancelled';

    /**
     * Applies the shipping information from the events to FB_Sales_Order__c.
     *
     * - Unknown order numbers are ignored.
     * - Cancelled orders are never changed.
     * - When several events in one call reference the same order, the last
     *   event in the list wins.
     *
     * @param events The platform events delivered to the trigger.
     */
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Keep only the last event per order (list order = publish order).
        Map<String, FB_Shipment_Event__e> latestEventByOrderNumber = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e evt : events) {
            if (evt == null) {
                continue;
            }
            String orderNumberKey = normaliseOrderNumber(evt.Order_Number__c);
            if (orderNumberKey == null) {
                continue;
            }
            // Overwriting the map entry makes the last event for an order win.
            latestEventByOrderNumber.put(orderNumberKey, evt);
        }

        if (latestEventByOrderNumber.isEmpty()) {
            return;
        }

        // Single SOQL query for the whole batch.
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :latestEventByOrderNumber.keySet()
        ];

        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        for (FB_Sales_Order__c order : orders) {
            // Cancelled orders are never changed.
            if (STATUS_CANCELLED.equals(order.Status__c)) {
                continue;
            }

            FB_Shipment_Event__e evt = latestEventByOrderNumber.get(normaliseOrderNumber(order.Order_Number__c));
            if (evt == null) {
                continue;
            }

            order.Status__c = STATUS_SHIPPED;
            order.Tracking_Number__c = evt.Tracking_Number__c;
            order.Carrier__c = evt.Carrier__c;
            order.Shipped_Date__c = Date.today();
            ordersToUpdate.add(order);
        }

        // Single DML statement for the whole batch.
        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }

    /**
     * Order numbers are a unique external id that is always upper case;
     * normalising keeps matching and de-duplication case-insensitive and
     * immune to stray whitespace.
     */
    private static String normaliseOrderNumber(String orderNumber) {
        if (String.isBlank(orderNumber)) {
            return null;
        }
        return orderNumber.trim().toUpperCase();
    }
}
