/**
 * Keeps the Account fields FB_Open_Pipeline__c (sum of Amount of the account's
 * open opportunities) and FB_Open_Opportunities__c (count of the account's open
 * opportunities) correct.
 *
 * Both values are re-computed from the database on every opportunity DML
 * statement instead of being derived from Trigger.old/Trigger.new deltas or
 * cached in static variables. That keeps them correct for several DML
 * statements on the same records inside one transaction (a Flow followed by
 * Apex, a test method, ...) and for batches of up to 200 opportunities per
 * trigger invocation.
 */
public without sharing class OpportunityPipelineHandler {

    /**
     * Entry point called by OpportunityTrigger for insert, update, delete and
     * undelete. Either list may be null: Trigger.new is null for delete and
     * Trigger.old is null for insert/undelete.
     *
     * Sharing is deliberately not enforced: the totals have to reflect every
     * open opportunity of the account, not only the ones visible to the user
     * whose DML caused the trigger to run.
     */
    public static void updateAccountTotals(
        List<Opportunity> newOpportunities,
        List<Opportunity> oldOpportunities
    ) {
        Set<Id> accountIds = collectAccountIds(newOpportunities, oldOpportunities);
        if (accountIds.isEmpty()) {
            return;
        }

        // One aggregate row per account that has open opportunities. An account
        // without open opportunities is absent from the maps and therefore gets
        // 0 / 0 below, so it is never left blank.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Decimal> openCountByAccount = new Map<Id, Decimal>();
        for (AggregateResult result : [
            SELECT AccountId accountId,
                   SUM(Amount) totalAmount,
                   COUNT(Id) totalOpen
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');

            // SUM ignores blank amounts and returns null when every amount of
            // the group is blank; blank amounts count as 0.
            Decimal pipeline = 0;
            if (result.get('totalAmount') != null) {
                pipeline = (Decimal) result.get('totalAmount');
            }
            pipelineByAccount.put(accountId, pipeline);

            Decimal openCount = (Integer) result.get('totalOpen');
            openCountByAccount.put(accountId, openCount);
        }

        // Rating is selected on purpose: the legacy AccountTrigger copies
        // Trigger.newMap<account>.Rating onto every open opportunity. Writing
        // partial Account records without Rating would blank the rating of all
        // open opportunities of the account.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, Rating, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = 0;
            if (pipelineByAccount.containsKey(account.Id)) {
                newPipeline = pipelineByAccount.get(account.Id);
            }
            Decimal newOpenCount = 0;
            if (openCountByAccount.containsKey(account.Id)) {
                newOpenCount = openCountByAccount.get(account.Id);
            }

            // Only accounts whose totals really changed are written. Writing an
            // unchanged value would re-enter the legacy AccountTrigger, which
            // updates opportunities, which would re-enter this handler again and
            // again. Skipping unchanged accounts breaks that loop while still
            // handling nested DML that does change the totals.
            if (newPipeline == account.FB_Open_Pipeline__c
                && newOpenCount == account.FB_Open_Opportunities__c) {
                continue;
            }

            account.FB_Open_Pipeline__c = newPipeline;
            account.FB_Open_Opportunities__c = newOpenCount;
            accountsToUpdate.add(account);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    /**
     * Collects the accounts of both the new and the old version of the records.
     * An update can move an opportunity to another account, so both accounts
     * have to be recalculated. Opportunities without an account are ignored.
     */
    private static Set<Id> collectAccountIds(
        List<Opportunity> newOpportunities,
        List<Opportunity> oldOpportunities
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (newOpportunities != null) {
            for (Opportunity opportunity : newOpportunities) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }
        if (oldOpportunities != null) {
            for (Opportunity opportunity : oldOpportunities) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }
        return accountIds;
    }
}
