/**
 * Deletes expired FB_Integration_Log__c records.
 *
 * Retention policy (measured from CreatedDate):
 *  - Level__c = 'ERROR'                                 -> kept for 180 days
 *  - anything else, including a blank Level__c          -> kept for 30 days
 *
 * scheduleNightly() registers the job to run every day at 02:00.
 *
 * Deletions are performed in bulk and bounded by the Apex transaction limits
 * (10,000 DML rows per transaction). Anything left over is picked up by the
 * next nightly run.
 */
public without sharing class LogPurgeJob implements Schedulable {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String CRON_DAILY_AT_0200 = '0 0 2 * * ?';

    private static final Integer RETENTION_DAYS_DEFAULT = 30;
    private static final Integer RETENTION_DAYS_ERROR = 180;

    /** Rows per delete statement; keeps each statement well within limits. */
    private static final Integer DELETE_CHUNK_SIZE = 1000;

    /** Apex allows a maximum of 10,000 DML rows per transaction. */
    private static final Integer MAX_DML_ROWS_PER_TRANSACTION = 10000;

    /** Required no-argument constructor so the class can be scheduled. */
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        purgeExpiredLogs();
    }

    /**
     * Schedules this job to run every day at 02:00 under the name
     * 'Log purge (nightly)'.
     *
     * @return the Id returned by the scheduling call.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_DAILY_AT_0200, new LogPurgeJob());
    }

    /**
     * Deletes expired logs in bulk, up to the transaction DML row limit.
     */
    @TestVisible
    private static void purgeExpiredLogs() {
        DateTime now = System.now();
        DateTime cutoffDefault = now.addDays(-RETENTION_DAYS_DEFAULT);
        DateTime cutoffError = now.addDays(-RETENTION_DAYS_ERROR);

        Integer rowsProcessed = 0;

        while (rowsProcessed < MAX_DML_ROWS_PER_TRANSACTION) {
            Integer chunkSize = Math.min(
                DELETE_CHUNK_SIZE,
                MAX_DML_ROWS_PER_TRANSACTION - rowsProcessed
            );

            // NOTE: a plain "Level__c != 'ERROR'" would also drop rows where
            // Level__c is null, so blank values are handled explicitly.
            List<FB_Integration_Log__c> expired = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (Level__c = 'ERROR' AND CreatedDate < :cutoffError)
                   OR ((Level__c = null OR Level__c != 'ERROR') AND CreatedDate < :cutoffDefault)
                ORDER BY CreatedDate
                LIMIT :chunkSize
            ];

            if (expired.isEmpty()) {
                return;
            }

            rowsProcessed += expired.size();

            Integer deleted = 0;
            List<Database.DeleteResult> results = Database.delete(expired, false);
            for (Database.DeleteResult result : results) {
                if (result.isSuccess()) {
                    deleted++;
                }
            }

            // If nothing in the chunk could be deleted (e.g. rows held by a
            // restricted-delete relationship), stop instead of looping forever.
            if (deleted == 0) {
                return;
            }
        }
    }
}
