/**
 * Central wiring of the fflib Application factories.
 *
 * The factories are public static fields so tests can replace the real
 * implementations with fflib-apex-mocks via their setMock methods.
 *
 * The order of the SObjectType entries in the UnitOfWork list is significant:
 * fflib_SObjectUnitOfWork performs DML in that order, so parent records are
 * inserted before the records that reference them and the junction record is
 * inserted last.
 */
public inherited sharing class Application
{
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<Schema.SObjectType>
            {
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type>
