public with sharing class Opportunities extends fflib_SObjectDomain
{
	private static final String STAGE_CLOSED_WON = 'Closed Won';

	public Opportunities(List<SObject> sObjectList)
	{
		super(sObjectList);
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}

	public override void onAfterInsert()
	{
		Set<Id> opportunityIds = new Set<Id>();

		for (SObject record : Records)
		{
			Opportunity opportunity = (Opportunity) record;

			if (isClosedWon(opportunity.StageName))
			{
				opportunityIds.add(opportunity.Id);
			}
		}

		startFulfilment(opportunityIds);
	}

	public override void onAfterUpdate(Map<Id, SObject> existingRecords)
	{
		Set<Id> opportunityIds = new Set<Id>();

		for (SObject record : Records)
		{
			Opportunity opportunity = (Opportunity) record;

			// Only a transition into Closed Won qualifies; re-saving an
			// opportunity that is already Closed Won does not.
			if (!isClosedWon(opportunity.StageName))
			{
				continue;
			}

			Opportunity existingOpportunity = (Opportunity) existingRecords.get(opportunity.Id);

			if (existingOpportunity == null || !isClosedWon(existingOpportunity.StageName))
			{
				opportunityIds.add(opportunity.Id);
			}
		}

		startFulfilment(opportunityIds);
	}

	private static Boolean isClosedWon(String stageName)
	{
		// Apex String comparison with == is case-insensitive; a null stage is never a match.
		return STAGE_CLOSED_WON == stageName;
	}

	private static void startFulfilment(Set<Id> opportunityIds)
	{
		// Called at most once per trigger invocation, and never with an empty set.
		if (opportunityIds.isEmpty())
		{
			return;
		}

		IOpportunityFulfilmentService fulfilmentService =
			(IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

		fulfilmentService.startFulfilment(opportunityIds);
	}
}
