            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);
            if (contactLastNames == null) {
                continue;
            }

            for (String contactLastName : contactLastNames) {
                Contact contactRecord = new Contact(LastName = contactLastName);
                uow.registerNew(contactRecord, Contact.AccountId, accountRecord);
            }
        }

        uow.commitWork();

        return createdAccounts;
    }
