/**
 * Closes opportunities as Closed Won and notifies Fulfilment of each won deal
 * through the Deal_Won__e platform event.
 *
 * Everything (the opportunity updates and the event publication) is registered
 * with a single fflib unit of work and committed once. The events are registered
 * for after-success publication, so Fulfilment is only told about deals that were
 * actually saved; if the DML fails the unit of work rolls back, publishes nothing
 * and rethrows to the caller.
 */
public inherited sharing class OpportunityWinService
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Marks the given opportunities as Closed Won (CloseDate = today) and publishes
     * one Deal_Won__e per opportunity that this call actually closes.
     *
     * @param opportunityIds The ids of the opportunities to close. Null or empty returns 0.
     * @return The number of opportunities closed by this call.
     */
    public static Integer markWon(Set<Id> opportunityIds)
    {
        if (opportunityIds == null || opportunityIds.isEmpty())
        {
            return 0;
        }

        // Ignore any null entries so the selector is never handed a meaningless id.
        Set<Id> idsToLoad = new Set<Id>();
        for (Id opportunityId : opportunityIds)
        {
            if (opportunityId != null)
            {
                idsToLoad.add(opportunityId);
            }
        }
        if (idsToLoad.isEmpty())
        {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(idsToLoad);
        if (opportunities == null || opportunities.isEmpty())
        {
            return 0;
        }

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunity : opportunities)
        {
            // Nothing to do for deals that are already Closed Won.
            if (opportunity.StageName == STAGE_CLOSED_WON)
            {
                continue;
            }

            opportunity.StageName = STAGE_CLOSED_WON;
            opportunity.CloseDate = Date.today();
            opportunitiesToClose.add(opportunity);
        }

        if (opportunitiesToClose.isEmpty())
        {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        List<SObject> dealWonEvents = new List<SObject>();

        for (Opportunity opportunity : opportunitiesToClose)
        {
            uow.registerDirty(opportunity);
            dealWonEvents.add(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opportunity.Id),
                    Amount__c = opportunity.Amount
                )
            );
        }

        // Publish only after the opportunity updates have been saved successfully.
        uow.registerPublishAfterSuccess(dealWonEvents);
        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
