```apex
/**
 * Keeps Account.Rating in sync with the open opportunity pipeline.
 *
 * Collects the affected account ids and hands them to AccountRatingService in a
 * single call. A 200-row CPQ batch therefore results in exactly ONE @future
 * invocation instead of 200 (the per-transaction limit is 50 future calls).
 */
trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {

    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isDelete) {
        // The account the deleted opportunity used to belong to needs a recalc.
        for (Opportunity opp : Trigger.old) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    } else {
        for (Opportunity opp : Trigger.new) {
            Opportunity oldOpp = Trigger.isUpdate ? Trigger.oldMap.get(opp.Id) : null;

            if (oldOpp != null) {
                Boolean affectsRating =
                    opp.StageName != oldOpp.StageName ||
                    opp.Amount != oldOpp.Amount ||
                    opp.AccountId != oldOpp.AccountId;

                if (!affectsRating) {
                    continue;
                }

                // Re-parented opportunity: the old account's pipeline changed too.
                if (oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                    accountIds.add(oldOpp.AccountId);
                }
            }

            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
```

