```apex
/**
 * Case closure feedback.
 *
 * When a Case changes from not closed to closed and it has a Contact, a CSAT
 * survey Task is created asynchronously (see CaseSurveyJob). The survey step is
 * expected to grow (a vendor integration is planned), so the work must never run
 * inline with the Case update.
 */
trigger CaseTrigger on Case (after update) {

    List<Case> newlyClosedCases = new List<Case>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        if (oldCase != null
                && !oldCase.IsClosed
                && newCase.IsClosed
                && newCase.ContactId != null) {
            newlyClosedCases.add(newCase);
        }
    }

    if (newlyClosedCases.isEmpty()) {
        return;
    }

    // One Queueable per Case keeps the work isolated: a failure on one survey
    // cannot affect any other. Apex allows at most Limits.getLimitQueueableJobs()
    // (50) queueable jobs per transaction, so one transaction that closes 200
    // Cases (the nightly cleanup) cannot give every Case its own job - the 51st
    // enqueueJob() throws an uncatchable limit exception and rolls back the whole
    // transaction. When the Cases fit in the available slots we enqueue exactly
    // one job per Case; when they do not, one bulk job covers the same Cases.
    Integer availableJobSlots = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();

    if (availableJobSlots <= 0) {
        // Another process in this transaction already used every job slot. Skip
        // the survey notification rather than failing and rolling back the Case
        // closures themselves.
        System.debug(
            LoggingLevel.WARN,
            'CaseTrigger: no queueable job slots left; CSAT surveys not queued for ' +
                newlyClosedCases.size() + ' case(s).'
        );
        return;
    }

    if (newlyClosedCases.size() <= availableJobSlots) {
        for (Case newCase : newlyClosedCases) {
            System.enqueueJob(new CaseSurveyJob(newCase.Id));
        }
    } else {
        List<Id> caseIds = new List<Id>();
        for (Case newCase : newlyClosedCases) {
            caseIds.add(newCase.Id);
        }
        System.enqueueJob(new CaseSurveyJob(caseIds));
    }
}
```

