```apex
public with sharing class AccountCountrySync {

    /**
     * After-update handler for AccountTrigger.
     *
     * When an account's BillingCountry changes, its contacts' MailingCountry is updated
     * to the new BillingCountry -- but only for contacts whose MailingCountry is blank or
     * matches the account's previous BillingCountry. Contacts that work abroad keep their
     * own MailingCountry, and contacts of accounts whose BillingCountry did not change
     * are never touched.
     *
     * Bulk-safe: one scoped SOQL statement and one DML statement per transaction,
     * regardless of how many accounts are in Trigger.new.
     *
     * @param newAccounts     the records from Trigger.new
     * @param oldAccountsById the records from Trigger.oldMap
     */
    public static void syncContactMailingCountry(
        List<Account> newAccounts,
        Map<Id, Account> oldAccountsById
    ) {
        // 1. Find only the accounts whose BillingCountry actually changed, and capture the
        //    value to copy down (new) and the value to match against (old).
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountsById.get(acc.Id);

            if (oldAcc == null || oldAcc.BillingCountry == acc.BillingCountry) {
                continue;
            }

            oldCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
            newCountryByAccountId.put(acc.Id, acc.BillingCountry);
        }

        // Nothing to do for this batch.
        if (newCountryByAccountId.isEmpty()) {
            return;
        }

        // 2. One query, scoped to the accounts we actually have to touch.
        //    (Querying every Contact in the org is impossible: 50k SOQL row / 6 MB heap limits.)
        Set<Id> accountIds = newCountryByAccountId.keySet();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            String newCountry = newCountryByAccountId.get(con.AccountId);
            String oldCountry = oldCountryByAccountId.get(con.AccountId);

            // Only the contacts that follow the headquarters move: blank MailingCountry,
            // or one that matched the account's previous BillingCountry. Everything else
            // (contacts working abroad) is deliberately left alone.
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // 3. One DML statement for the whole trigger batch.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

