import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';
import ACCOUNT_NAME from '@salesforce/schema/Account.Name';
import ACCOUNT_INDUSTRY from '@salesforce/schema/Account.Industry';
import ACCOUNT_ANNUAL_REVENUE from '@salesforce/schema/Account.AnnualRevenue';
import ACCOUNT_OWNER_NAME from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    ACCOUNT_NAME,
    ACCOUNT_INDUSTRY,
    ACCOUNT_ANNUAL_REVENUE,
    ACCOUNT_OWNER_NAME
];

export default class AccountHeader extends LightningElement {
    _recordId;
    record;
    error;

    /**
     * Record Id supplied by the record page. The setter guarantees that a
     * change of record (e.g. a reused console tab) resets any previously
     * loaded data / error so the wire adapter provisions the new record.
     */
    @api
    get recordId() {
        return this._recordId;
    }

    set recordId(value) {
        if (value !== this._recordId) {
            this._recordId = value;
            this.record = undefined;
            this.error = undefined;
        }
    }

    @wire(getRecord, {
        recordId: '$_recordId',
        fields: FIELDS
    })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        return (
            (this.error && this.error.body && this.error.body.message) ||
            (this.error && this.error.message) ||
            'An unexpected error occurred.'
        );
    }

    get accountName() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get hasIndustry() {
        const industry = this.industry;
        return industry !== undefined && industry !== null && industry !== '';
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        return this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }
}
