    handleClick(event) {
        const action = event.currentTarget.dataset.action;

        switch (action) {
            case 'new-contact':
                this.navigateToNewContact();
                break;
            case 'contacts':
                this.navigateToContacts();
                break;
            case 'edit':
                this.navigateToEdit();
                break;
            default:
