import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    results = [];
    error;

    // Latest trimmed search term, used when the debounce timer fires.
    searchTerm = '';

    _isConnected = false;
    _debounceTimerId;
    // Monotonically increasing id; only the newest request may update the UI.
    _requestCounter = 0;

    connectedCallback() {
        this._isConnected = true;
    }

    disconnectedCallback() {
        // Cancel the pending debounce and invalidate anything in flight so no
        // search can run or update the UI after the component is removed.
        this._isConnected = false;
        this._cancelPendingSearch();
    }

    handleSearchChange(event) {
        const value = event.target && event.target.value ? event.target.value : '';
        this.searchTerm = value.trim();

        // Every keystroke cancels the previously scheduled search.
        this._cancelPendingSearch();

        if (this.searchTerm.length < MIN_SEARCH_LENGTH) {
            this._clearResults();
            return;
        }

        this._debounceTimerId = setTimeout(() => {
            this._debounceTimerId = undefined;
            this._runSearch(this.searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    get errorMessage() {
        if (!this.error) {
            return '';
        }
        return (
            (this.error.body && this.error.body.message) ||
            this.error.message ||
            ''
        );
    }

    _runSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._requestCounter;
        this.error = undefined;

        searchContacts({ searchTerm })
            .then((data) => {
                // Ignore stale responses: out-of-order or after removal.
                if (!this._isConnected || requestId !== this._requestCounter) {
                    return;
                }
                this.results = Array.isArray(data) ? data : [];
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._requestCounter) {
                    return;
                }
                this.results = [];
                this.error = error;
            });
    }

    _cancelPendingSearch() {
        if (this._debounceTimerId !== undefined) {
            clearTimeout(this._debounceTimerId);
            this._debounceTimerId = undefined;
        }
        // Invalidate any in-flight request so a stale response cannot win.
        this._requestCounter += 1;
    }

    _clearResults() {
        this.results = [];
        this.error = undefined;
    }
}
