import FavoriteAdd from '@salesforce/label/c.Favorite_Add';
import FavoriteRemove from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    // State shown by the toggle. It is deliberately kept out of the @api accessor
    // so the optimistic update never reassigns a public property
    // (`@lwc/lwc/no-api-reassignments`).
    _favorite = false;

    /**
     * Whether the record is a favourite. Owned by the parent: whenever the parent
     * assigns a value (for example after a server refresh) the setter runs and the
     * button then reflects that value.
     */
    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = Boolean(value);
    }

    // `aria-pressed` must be the literal string "true" or "false".
    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    // Label of the action a click performs: Remove when it is already a favourite.
    get actionLabel() {
        return this._favorite ? FavoriteRemove : FavoriteAdd;
    }

    // Filled border communicates the pressed state.
    get buttonClass() {
        return this._favorite
            ? 'slds-button slds-button_icon slds-button_icon-border-filled'
            : 'slds-button slds-button_icon slds-button_icon-border';
    }

    // Gold when it is a favourite, neutral otherwise.
    get iconVariant() {
        return this._favorite ? 'warning' : 'bare';
    }

    handleClick() {
        // Optimistic UI: flip the state shown right away ...
        this._favorite = !this._favorite;

        // ... then let the parent persist the new value.
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                bubbles: true,
                composed: true,
                detail: {
                    favorite: this._favorite
                }
            })
        );
    }
