import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    /**
     * Id of the Account record the component is placed on.
     * Populated by the record page before connectedCallback runs.
     */
    @api recordId;

    opportunities;
    error;
    isLoading = false;

    connectedCallback() {
        this.loadOpenOpportunities();
    }

    handleRetry() {
        this.loadOpenOpportunities();
    }

    loadOpenOpportunities() {
        this.isLoading = true;
        this.error = undefined;

        return getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = Array.isArray(result) ? result : [];
                this.error = undefined;
            })
            .catch((error) => {
                this.opportunities = undefined;
                this.error = error;
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    get hasError() {
        return this.error !== undefined && this.error !== null;
    }

    get errorMessage() {
        const body = this.error && this.error.body;
        if (body && body.message) {
            return body.message;
        }
        if (Array.isArray(body) && body.length > 0) {
            return body.map((item) => item.message).join('; ');
        }
        return (this.error && this.error.message) || 'An unexpected error occurred.';
    }

    get hasOpportunities() {
        return Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }
}
