import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const ROW_ACTIONS = [
    { label: 'View', name: 'view' },
    { label: 'Edit', name: 'edit' },
    { label: 'Delete', name: 'delete' }
];

const COLUMNS = [
    { label: 'Name', fieldName: 'Name' },
    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    { type: 'action', typeAttributes: { rowActions: ROW_ACTIONS } }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    /**
     * Rows rendered by the datatable. This is a defensive copy of the data
     * provided by the parent so removing a deleted row never mutates the
     * parent's array.
     */
    tableRows = [];

    _opportunities = [];

    /**
     * Public property: array of { Id, Name, StageName, Amount } records passed
     * in by the parent. A new array supplied later replaces the rendered rows.
     */
    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = Array.isArray(value) ? value : [];
        this.tableRows = this._opportunities.map((row) => ({ ...row }));
    }

    handleRowAction(event) {
        const { action, row } = event.detail;

        switch (action.name) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: 'Opportunity',
                actionName
            }
        });
    }

    async confirmAndDelete(row) {
        const confirmed = await LightningConfirm.open({
            label: 'Delete Opportunity',
            message: `Are you sure you want to delete ${row.Name || 'this opportunity'}?`,
            theme: 'warning',
            variant: 'headerless'
        });

        // User cancelled: nothing to do.
        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove the row from the table without mutating the parent's array.
            this.tableRows = this.tableRows.filter((item) => item.Id !== row.Id);

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
                })
            );
        } catch (error) {
            // Keep the row and surface the platform error message.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: error?.body?.message || error?.message,
                    variant: 'error'
                })
            );
        }
    }
}
