export default class OrderLinesPanel extends LightningElement {
    /** @type {{ key: string, productName: string, quantity: number }[]} */
    _lines = [];

    /** True while the submit error message must be displayed. */
    showError = false;

    /** Lines to edit. Normalized to an array so rendering is always safe. */
    @api
    get lines() {
        return this._lines;
    }

    set lines(value) {
        this._lines = Array.isArray(value) ? value : [];
    }

    /** The rendered line editors, in display order. */
    get editors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    /** Resets every line editor to its default quantity. */
    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    /**
     * Validates every line editor before deciding on the outcome. `map` never
     * short-circuits, so each editor reports its errors even when an earlier
     * one already failed.
     */
    handleSubmit() {
        const editors = this.editors;
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((isValid) => Boolean(isValid));

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const lines = editors.map((editor) => editor.getValue());

        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines },
                bubbles: true,
                composed: true
            })
        );
    }
}
