import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    stats;
    error;

    _pollTimer;
    _requestInFlight = false;
    _requestToken = 0;
    _isActive = false;
    _visibilityHandler;

    connectedCallback() {
        this._isActive = true;

        // Keep one stable reference so the listener can be removed on disconnect.
        this._visibilityHandler = this._handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._visibilityHandler);

        // Defensive reset: guarantees a single polling loop and no stale requests
        // if connectedCallback runs again on this same instance.
        this._stopPolling();
        this._invalidateRequests();

        if (document.visibilityState !== 'hidden') {
            this.loadStats();
            this._startPolling();
        }
    }

    disconnectedCallback() {
        this._isActive = false;

        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = undefined;
        }

        this._stopPolling();
        // Ignore anything that settles after removal and free the in-flight slot.
        this._invalidateRequests();
    }

    /**
     * Loads the stats imperatively. Does nothing when the page is hidden or when a
     * previous request is still in flight (that refresh is simply skipped).
     */
    loadStats() {
        if (this._requestInFlight) {
            return;
        }

        if (typeof document === 'undefined' || document.visibilityState === 'hidden') {
            return;
        }

        this._requestInFlight = true;
        const token = ++this._requestToken;

        getQueueStats()
            .then((result) => {
                if (!this._isActive || token !== this._requestToken) {
                    return;
                }
                this.stats = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isActive || token !== this._requestToken) {
                    return;
                }
                this.error = this._extractErrorMessage(error);
            })
            .finally(() => {
                if (token === this._requestToken) {
                    this._requestInFlight = false;
                }
            });
    }

    _handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            // Make no requests while the page is in the background.
            this._stopPolling();
            return;
        }

        // Visible again: refresh now, then continue on a fresh 60-second cadence.
        this._stopPolling();
        this.loadStats();
        this._startPolling();
    }

    _startPolling() {
        this._stopPolling();
        this._pollTimer = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._pollTimer) {
            clearInterval(this._pollTimer);
            this._pollTimer = undefined;
        }
    }

    _invalidateRequests() {
        this._requestToken++;
        this._requestInFlight = false;
    }

    _extractErrorMessage(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && Array.isArray(error.body) && error.body[0] && error.body[0].message) {
            return error.body[0].message;
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }
}
