import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        // Keep each field's current value from the change event.
        const field =
            event.target?.dataset?.field ?? event.currentTarget?.dataset?.field;

        if (field) {
            this[field] = event.detail.value;
        }
    }

    handleRegister() {
        const inputs = Array.from(
            this.template.querySelectorAll('lightning-input')
        );
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );

        // 1. Reject free email domains before any other validation runs.
        if (emailInput) {
            const domain = this.email.trim().toLowerCase().split('@').pop();
            if (FREE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // 2. Report validity on every input so all messages show at once.
        //    map() (not every()) guarantees every reportValidity() is called.
        const isValid = inputs
            .map((input) => input.reportValidity())
            .every(Boolean);

        // 3. Stop if anything is invalid, otherwise call Apex imperatively.
        if (!isValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
