import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Working copy of the tasks. All mutations happen on this copy only.
    items = [];
    newLabel = '';
    nextId = 1;

    // The value as it was handed over by the parent; never mutated here.
    _tasks = [];

    @api
    heading;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        const nextTasks = Array.isArray(value) ? value : [];

        // Only a new list from the parent replaces the working copy, so a parent
        // re-render that passes the same array cannot wipe out local changes.
        if (nextTasks === this._tasks) {
            return;
        }

        this._tasks = nextTasks;
        this.items = nextTasks.map((task) => ({ ...task }));
    }

    // Display only: `heading` keeps the value set by the parent (and stays
    // reactive to later changes), the upper-casing happens here.
    get displayHeading() {
        return this.heading == null ? '' : String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        let value = '';

        if (event && event.detail && event.detail.value != null) {
            value = event.detail.value;
        } else if (event && event.target && event.target.value != null) {
            value = event.target.value;
        }

        this.newLabel = value == null ? '' : String(value);
    }

    handleAdd() {
        const label = (this.newLabel == null ? '' : String(this.newLabel)).trim();

        // Empty or whitespace-only labels are ignored: nothing added, no event.
        if (label === '') {
            return;
        }

        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const source = (event && (event.currentTarget || event.target)) || null;
        const id = source && source.dataset ? source.dataset.id : null;

        if (id == null) {
            return;
        }

        // `dataset` values are strings, ids may be numbers: compare as strings.
        this.items = this.items.map((task) =>
            String(task.id) === String(id) ? { ...task, done: !task.done } : task
        );
    }

    generateId() {
        const usedIds = new Set(this.items.map((task) => String(task.id)));
        let id = `new-${this.nextId++}`;

        while (usedIds.has(id)) {
            id = `new-${this.nextId++}`;
        }

        return id;
    }
}
