/**
 * GauAllocationService
 *
 * Percentage based General Accounting Unit (GAU) allocations for NPSP gifts (Opportunities).
 *
 * Every allocation is written with npsp__Percent__c populated, which is what keeps the split
 * correct over time: NPSP derives npsp__Amount__c from the gift amount and recalculates it
 * whenever that amount changes. A 60/40 split of a $1,000 gift therefore becomes $1,200/$800
 * automatically when the gift is corrected to $2,000, with no further Apex required.
 *
 * The whole operation is validated before the first DML statement and executed as a single
 * all-or-nothing unit of work: the allocations on the Opportunity are replaced by exactly one
 * allocation per GAU entry, and a failure leaves the previous set untouched.
 */
public with sharing class GauAllocationService {

    /** Raised for invalid input or unmet business rules. */
    public class AllocationException extends Exception {}

    /** Percentages may total 100 at most; anything below 100 leaves the remainder unallocated. */
    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /** Currency amounts are stored with two decimals. */
    private static final Integer CURRENCY_SCALE = 2;

    /** CurrencyIsoCode only exists in multi-currency orgs. */
    private static final Boolean HAS_OPPORTUNITY_CURRENCY =
        Opportunity.SObjectType.getDescribe().fields.getMap().containsKey('CurrencyIsoCode');
    private static final Boolean HAS_ALLOCATION_CURRENCY =
        npsp__Allocation__c.SObjectType.getDescribe().fields.getMap().containsKey('CurrencyIsoCode');

    /**
     * Replaces every GAU allocation on the Opportunity with one allocation per map entry.
     *
     * @param opportunityId  Id of the Opportunity whose allocations are replaced.
     * @param percentByGauId General Accounting Unit Id to percentage (60 means 60%).
     * @return the inserted allocations, one per map entry.
     * @throws AllocationException if the map is null or empty, a percentage is null or not
     *         greater than 0, the percentages total more than 100, or a GAU is missing or
     *         inactive. No data is changed when this exception is thrown.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---- Validation: everything below runs before the first DML statement. ----
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        validatePercentages(percentByGauId);
        validateGaus(percentByGauId.keySet());

        // ---- Unit of work: one query per object, no queries or DML inside loops. ----
        Opportunity gift = queryOpportunity(opportunityId);
        List<npsp__Allocation__c> allocations = buildAllocations(opportunityId, gift, percentByGauId);
        replaceAllocations(opportunityId, allocations);

        return allocations;
    }

    // -------------------------------------------------------------------------
    // Validation
    // -------------------------------------------------------------------------

    private static void validatePercentages(Map<Id, Decimal> percentByGauId) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id cannot be null.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Every allocation percentage must be greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'Allocation percentages cannot total more than 100 percent.'
            );
        }
    }

    private static void validateGaus(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gausById = queryGaus(gauIds);

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'GAU ' + String.valueOf(gauId) + ' does not exist.'
                );
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'GAU "' + gau.Name + '" is inactive and cannot receive allocations.'
                );
            }
        }
    }

    private static Map<Id, npsp__General_Accounting_Unit__c> queryGaus(Set<Id> gauIds) {
        return new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );
    }

    private static Opportunity queryOpportunity(Id opportunityId) {
        // CurrencyIsoCode only exists in multi-currency orgs, so the field list is dynamic.
        String fields = 'Id, Amount';
        if (HAS_OPPORTUNITY_CURRENCY) {
            fields += ', CurrencyIsoCode';
        }

        List<Opportunity> gifts = Database.query(
            'SELECT ' + fields + ' FROM Opportunity WHERE Id = :opportunityId'
        );
        if (gifts.isEmpty()) {
            throw new AllocationException(
                'Opportunity ' + String.valueOf(opportunityId) + ' does not exist.'
            );
        }
        return gifts[0];
    }

    // -------------------------------------------------------------------------
    // Allocation creation and replacement
    // -------------------------------------------------------------------------

    private static List<npsp__Allocation__c> buildAllocations(
        Id opportunityId,
        Opportunity gift,
        Map<Id, Decimal> percentByGauId
    ) {
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);

            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent
            );

            // Seed the amount from the current gift amount. NPSP keeps it in sync with the
            // percentage from now on, including later corrections to the gift amount.
            if (gift.Amount != null) {
                allocation.npsp__Amount__c =
                    (gift.Amount * percent / 100).setScale(CURRENCY_SCALE, RoundingMode.HALF_UP);
            }

            // Keep the allocation in the gift's currency in multi-currency orgs.
            if (HAS_ALLOCATION_CURRENCY && HAS_OPPORTUNITY_CURRENCY) {
                allocation.put('CurrencyIsoCode', gift.get('CurrencyIsoCode'));
            }

            allocations.add(allocation);
        }

        return allocations;
    }

    private static void replaceAllocations(Id opportunityId, List<npsp__Allocation__c> allocations) {
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        Savepoint beforeReplace = Database.setSavepoint();
        try {
            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }
            insert allocations;
        } catch (Exception ex) {
            // Never leave a gift with a partial or missing set of allocations.
            Database.rollback(beforeReplace);
            throw ex;
        }
    }
}
