/**
 * Turns a donation into a fixed installment plan.
 *
 * Paid and written-off payments are history: they are never modified or deleted.
 * Every other payment on the opportunity is deleted and replaced with
 * numberOfPayments unpaid installments that add up exactly to the outstanding
 * amount of the donation.
 */
public with sharing class PaymentPlanService {

    /** Thrown when a payment plan cannot be created. The org is left unchanged. */
    public class PaymentPlanException extends Exception {}

    /** NPSP payment amounts are currency fields, i.e. two decimal places. */
    private static final Integer CURRENCY_SCALE = 2;

    /**
     * Replaces the open payments of a donation with numberOfPayments unpaid installments.
     *
     * Payment i (0-based) is scheduled on firstPaymentDate.addMonths(i). Every installment
     * is the outstanding amount divided by numberOfPayments, rounded down to the cent with
     * RoundingMode.DOWN. The last installment also absorbs the rounding remainder so that
     * the new payments add up exactly to the outstanding amount (the opportunity Amount
     * minus the amounts of its paid and written-off payments).
     *
     * @param opportunityId    The donation to reschedule.
     * @param numberOfPayments The number of installments to create; must be at least 1.
     * @param firstPaymentDate The scheduled date of the first installment.
     * @return the inserted payments, in schedule order.
     * @throws PaymentPlanException when numberOfPayments is null or less than 1, when the
     *         opportunity is closed, or when the outstanding amount is not greater than
     *         zero. Nothing is changed in the org when this exception is thrown.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // Validate everything up front so an invalid request never changes any data.
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        Opportunity opportunity = loadOpportunity(opportunityId);

        if (opportunity.IsClosed) {
            throw new PaymentPlanException('Only open opportunities can be put on a payment plan.');
        }

        Decimal historyAmount = 0;
        List<npe01__OppPayment__c> openPayments = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : opportunity.npe01__OppPayment__r) {
            if (isHistory(payment)) {
                // Paid and written-off payments stay exactly as they are, but they have
                // already been settled and must not be scheduled again.
                Decimal settledAmount = payment.npe01__Payment_Amount__c;
                if (settledAmount != null) {
                    historyAmount += settledAmount;
                }
            } else {
                openPayments.add(payment);
            }
        }

        Decimal donationAmount = opportunity.Amount;
        if (donationAmount == null) {
            donationAmount = 0;
        }

        Decimal outstandingAmount = donationAmount - historyAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('The outstanding amount must be greater than zero.');
        }

        List<npe01__OppPayment__c> installments = buildInstallments(
            opportunityId,
            numberOfPayments,
            firstPaymentDate,
            outstandingAmount
        );

        // Deleting and inserting is one atomic step: either the whole new schedule is
        // created or the previous schedule is restored exactly as it was.
        Savepoint beforeChange = Database.setSavepoint();
        try {
            if (!openPayments.isEmpty()) {
                Database.delete(openPayments, true);
            }
            Database.insert(installments, true);
        } catch (Exception e) {
            Database.rollback(beforeChange);
            throw e;
        }

        return installments;
    }

    /** Paid and written-off payments are history and must be left untouched. */
    private static Boolean isHistory(npe01__OppPayment__c payment) {
        return payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true;
    }

    /** Loads the donation and all of its payments in a single query. */
    private static Opportunity loadOpportunity(Id opportunityId) {
        List<Opportunity> opportunities = [
            SELECT Id,
                   Amount,
                   IsClosed,
                   (SELECT Id,
                           npe01__Payment_Amount__c,
                           npe01__Paid__c,
                           npe01__Written_Off__c
                      FROM npe01__OppPayment__r)
              FROM Opportunity
             WHERE Id = :opportunityId
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity ' + opportunityId + ' was not found.');
        }

        return opportunities[0];
    }

    /**
     * Builds the new unpaid installments in schedule order. All but the last payment get
     * the amount rounded down to the cent; the last one absorbs the remainder so that the
     * payments sum up exactly to the outstanding amount.
     */
    private static List<npe01__OppPayment__c> buildInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate,
        Decimal outstandingAmount
    ) {
        Decimal installmentAmount =
            (outstandingAmount / numberOfPayments).setScale(CURRENCY_SCALE, RoundingMode.DOWN);

        List<npe01__OppPayment__c> installments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal paymentAmount = installmentAmount;
            if (i == numberOfPayments - 1) {
                // The final installment absorbs the cents left over by rounding down.
                paymentAmount = outstandingAmount - (installmentAmount * (numberOfPayments - 1));
            }

            installments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = paymentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        return installments;
    }
}
