/**
 * NPSP Relationship service used by the student-system family link import.
 *
 * NPSP is configured with the "List Setting" reciprocal method and the "Parent"
 * Relationship Lookup (Male: Son, Female: Daughter, Neutral: Child). For every pair
 * exactly one record is inserted, with the child as npe4__Contact__c and
 * npe4__Type__c = 'Parent', so the child sees the parent as their Parent.
 * NPSP's trigger creates the mirror record itself, taking Son / Daughter / Child
 * from the "Parent" Relationship Lookup based on the child's gender, and links the
 * two records through npe4__ReciprocalRelationship__c. Inserting both directions
 * ourselves would leave two relationships in each direction.
 *
 * Bulk safe: one SOQL query and one DML statement for any number of pairs.
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * Records each parent as the 'Parent' of the child, with status 'Current'.
     *
     * @param parentIdByChildId child Contact Id => parent Contact Id. Null or empty
     *        input does nothing. Pairs that already have any relationship between
     *        the two contacts, in either direction, are skipped so the import can be
     *        re-run safely. Self-pairs and null values are ignored.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Contacts taking part in usable pairs.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (isValidPair(childId, parentId)) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Single SOQL: every relationship between any two of the involved contacts,
        // which covers both directions of each requested pair.
        Set<String> existingKeys = new Set<String>();
        for (npe4__Relationship__c existingRel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
            AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingKeys.add(pairKey(existingRel.npe4__Contact__c, existingRel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> relationshipsToCreate = new List<npe4__Relationship__c>();
        Set<String> handledKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (!isValidPair(childId, parentId)) {
                continue;
            }

            String forwardKey = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);

            // A pair supplied more than once (including once in each direction) must
            // still end up with only one relationship per direction.
            if (handledKeys.contains(forwardKey) || handledKeys.contains(reverseKey)) {
                continue;
            }
            handledKeys.add(forwardKey);
            handledKeys.add(reverseKey);

            // Any existing relationship between the two contacts, in either
            // direction and of any type or status, makes this pair a no-op.
            if (existingKeys.contains(forwardKey) || existingKeys.contains(reverseKey)) {
                continue;
            }

            relationshipsToCreate.add(
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = TYPE_PARENT,
                    npe4__Status__c = STATUS_CURRENT
                )
            );
        }

        if (!relationshipsToCreate.isEmpty()) {
            // Single DML. NPSP's trigger creates the reciprocal record (Son /
            // Daughter / Child) and populates npe4__ReciprocalRelationship__c on
            // both records, so each pair ends up with exactly one relationship in
            // each direction.
            insert relationshipsToCreate;
        }
    }

    private static Boolean isValidPair(Id childId, Id parentId) {
        return childId != null && parentId != null && childId != parentId;
    }

    private static String pairKey(Id firstId, Id secondId) {
        return String.valueOf(firstId) + '|' + String.valueOf(secondId);
    }
}
