/**
 * OPP_MajorGiftFollowUp_TDTM
 * ===========================================================================
 * NPSP Table-Driven Trigger Management (TDTM) handler for the Opportunity object.
 *
 * Registered by the admin with an NPSP Trigger Handler record:
 *     Class          : OPP_MajorGiftFollowUp_TDTM
 *     Object         : Opportunity
 *     Trigger Action : AfterInsert;AfterUpdate
 *     Load Order     : 5
 *     Asynchronous   : false
 *
 * There is intentionally no Apex trigger. NPSP's TDTM dispatcher instantiates this
 * class and calls run(), so the admin can see, reorder and switch off the handler from
 * NPSP Settings > Trigger Configuration. Deactivating the Trigger Handler record stops
 * the class from running entirely.
 *
 * Behaviour:
 *   The first time an Opportunity qualifies as a major gift (StageName 'Closed Won' and
 *   Amount >= 5000) exactly one follow-up Task is created:
 *       Subject      : Major gift thank-you call
 *       Priority     : High
 *       Status       : Not Started
 *       WhatId       : the Opportunity
 *       WhoId        : the Opportunity's npsp__Primary_Contact__c (may be null)
 *       OwnerId      : the Opportunity owner
 *       ActivityDate : the Opportunity CloseDate + 3 days
 *
 *   An Opportunity only qualifies "for the first time" when it did not satisfy both
 *   conditions before the current save. That is what guarantees that editing a gift
 *   which already qualified never creates a second task, while still creating one when
 *   a gift becomes a major gift later (e.g. its Amount is increased past the threshold).
 *
 * Governor safety:
 *   Every field the handler needs is available from the trigger context itself, so it
 *   issues no SOQL at all and performs exactly one bulk DML statement for the whole
 *   trigger batch. 200 Opportunities are therefore processed in a single transaction.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer DAYS_UNTIL_THANK_YOU_CALL = 3;

    /**
     * TDTM entry point, called by NPSP's dispatcher for each registered trigger action.
     * Returns null because this handler performs its own single, bulk DML statement.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        Boolean isAfterInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isAfterUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        // Only the actions registered on the Trigger Handler record do any work.
        if (!isAfterInsert && !isAfterUpdate) {
            return null;
        }

        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        List<Task> thankYouCalls = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity gift = (Opportunity) newlist[i];

            if (!isMajorGift(gift)) {
                continue;
            }

            // On update, create the follow-up only when the gift becomes a major gift,
            // i.e. when it did not qualify before this save. This is what keeps an
            // already qualifying gift from ever getting a second task.
            if (isAfterUpdate) {
                Opportunity beforeUpdate = oldOpportunityAt(oldlist, i);
                if (beforeUpdate != null && isMajorGift(beforeUpdate)) {
                    continue;
                }
            }

            thankYouCalls.add(buildThankYouCall(gift));
        }

        // Single DML statement for the whole trigger batch (up to 200 rows).
        if (!thankYouCalls.isEmpty()) {
            insert thankYouCalls;
        }

        return null;
    }

    /** True when the Opportunity is Closed Won with an Amount of at least 5000. */
    private static Boolean isMajorGift(Opportunity gift) {
        return gift != null
            && gift.StageName != null
            && STAGE_CLOSED_WON.equalsIgnoreCase(gift.StageName)
            && gift.Amount != null
            && gift.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    /** Returns the "old" version of the record at the same index, or null if unavailable. */
    private static Opportunity oldOpportunityAt(List<SObject> oldlist, Integer index) {
        if (oldlist == null || index == null || index < 0 || index >= oldlist.size()) {
            return null;
        }
        return (Opportunity) oldlist[index];
    }

    /** Builds the major gift thank-you call follow-up Task for an Opportunity. */
    private static Task buildThankYouCall(Opportunity gift) {
        Date activityDate = null;
        if (gift.CloseDate != null) {
            activityDate = gift.CloseDate.addDays(DAYS_UNTIL_THANK_YOU_CALL);
        }

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = gift.Id,
            WhoId = gift.npsp__Primary_Contact__c,
            OwnerId = gift.OwnerId,
            ActivityDate = activityDate
        );
    }
}
