/**
 * Determines which records the running user is allowed to edit.
 *
 * Access is read straight from UserRecordAccess.HasEditAccess, so object
 * permissions, ownership, sharing rules, the role hierarchy and View All /
 * Modify All are evaluated by the platform itself instead of being
 * re-implemented in Apex.
 */
public with sharing class RecordAccessService {

    /**
     * Number of record IDs resolved per SOQL query. A UserRecordAccess query
     * only accepts a limited number of record IDs in its filter, so the input
     * is chunked. For 2,000 IDs this is exactly 20 queries, which stays inside
     * the agreed budget and leaves the rest of the transaction's governor
     * limits alone.
     */
    private static final Integer IDS_PER_QUERY = 100;

    /**
     * Returns the subset of recordIds that the running user can edit.
     *
     * @param recordIds Record IDs to evaluate. IDs may belong to different
     *                  objects. A null or empty input returns an empty set.
     * @return The IDs from recordIds that the running user has edit access to.
     *         Never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // A Set<Id> can contain nulls; they are never editable and would only
        // pollute the query filter, so they are dropped up front.
        List<Id> idsToCheck = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                idsToCheck.add(recordId);
            }
        }
        if (idsToCheck.isEmpty()) {
            return editable;
        }

        Id userId = UserInfo.getUserId();

        // One SOQL query per chunk: no queries inside loops over individual
        // records and no per-object queries, so mixed-object input cannot blow
        // the query budget.
        List<Id> chunk = new List<Id>();
        for (Id recordId : idsToCheck) {
            chunk.add(recordId);
            if (chunk.size() == IDS_PER_QUERY) {
                addEditableIds(chunk, userId, editable);
                chunk = new List<Id>();
            }
        }
        if (!chunk.isEmpty()) {
            addEditableIds(chunk, userId, editable);
        }

        return editable;
    }

    /**
     * Runs a single UserRecordAccess query for one chunk of IDs and collects
     * the IDs the running user can edit. Records the user cannot even read
     * return no row at all, which correctly means "not editable".
     *
     * @param recordIds Chunk of record IDs to resolve (any object mix).
     * @param userId    The running user.
     * @param editable  Collector for the editable record IDs.
     */
    private static void addEditableIds(List<Id> recordIds, Id userId, Set<Id> editable) {
        for (UserRecordAccess access : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :userId
                AND RecordId IN :recordIds
        ]) {
            if (access.HasEditAccess) {
                editable.add(access.RecordId);
            }
        }
    }
}
```

