public with sharing class DiscountApprovalService {

    private static final String LARGE_DISCOUNT_PERMISSION = 'Approve_Large_Discount';
    private static final Decimal SELF_APPROVAL_LIMIT = 15;

    /**
     * Returns true when the running user may approve the supplied discount.
     * Discounts from 0% up to and including 15% are approvable by anyone;
     * anything above 15% requires the Approve_Large_Discount custom permission.
     */
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }

        if (discountPercent <= SELF_APPROVAL_LIMIT) {
            return true;
        }

        // Evaluates the custom permission itself, so grants from profiles,
        // permission sets and permission set groups are all honoured.
        return FeatureManagement.checkPermission(LARGE_DISCOUNT_PERMISSION);
    }
}
