File: force-app/main/default/classes/EmployeeDirectoryService.cls
```apex
/**
 * Service for the employee directory component.
 *
 * Security model:
 *  - Sharing: the class runs "with sharing", so the SOQL respects the running
 *    user's record visibility (FB_Employee__c is Private OWD).
 *  - Object-level: if the running user cannot read FB_Employee__c, an empty
 *    list is returned instead of leaking records through system-mode SOQL.
 *  - Field-level: the three custom fields are queried only when the running
 *    user has read access to them, so the returned records genuinely do not
 *    contain the inaccessible fields (they are absent, not null).
 */
public with sharing class EmployeeDirectoryService {

    // Custom fields whose presence in the result is governed by FLS.
    private static final List<String> FLS_PROTECTED_FIELDS = new List<String>{
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    public static List<FB_Employee__c> getDirectory() {
        List<FB_Employee__c> directory = new List<FB_Employee__c>();

        // Object-level read access check. Apex SOQL runs in system mode, so a
        // query alone would return records even without object read access.
        Schema.DescribeSObjectResult employeeDescribe = FB_Employee__c.SObjectType.getDescribe();
        if (!employeeDescribe.isAccessible()) {
            return directory;
        }

        // Build the select list from fields the running user may read.
        Map<String, Schema.SObjectField> fieldMap = employeeDescribe.fields.getMap();
        List<String> fieldsToQuery = new List<String>{ 'Id', 'Name' };
        for (String fieldName : FLS_PROTECTED_FIELDS) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        // Only readable fields are selected, so inaccessible fields are never
        // populated on the returned records (not even with a null value).
        String soql =
            'SELECT ' + String.join(fieldsToQuery, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        // Single, bulk-safe query; "with sharing" restricts it to the records
        // the running user can see through sharing.
        directory = Database.query(soql);
        return directory;
    }
}
