/**
 * Trigger action that creates an onboarding Task for the owner of every newly
 * created customer Account (Type = 'Customer - Direct' or 'Customer - Channel').
 *
 * Registered on the Account after-insert context through the
 * Trigger_Action.TA_Account_CreateOnboardingTask custom metadata record.
 *
 * Bulk safety: all Tasks for a trigger context are collected and inserted with a
 * single DML statement, and no DML is issued at all when no Account qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer TASK_DUE_IN_DAYS = 7;
    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Task> onboardingTasks = new List<Task>();
        Date dueDate = Date.today().addDays(TASK_DUE_IN_DAYS);

        for (SObject record : triggerNew) {
            Account newAccount = (Account) record;
            if (newAccount == null || !CUSTOMER_TYPES.contains(newAccount.Type)) {
                continue;
            }
            onboardingTasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = newAccount.Id,
                    OwnerId = newAccount.OwnerId,
                    ActivityDate = dueDate,
                    Status = TASK_STATUS,
                    Priority = TASK_PRIORITY
                )
            );
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
```

