File: force-app/main/default/classes/AccountOwnershipService.cls
```apex
/**
 * Reassigns ownership of Accounts and of every Contact on those Accounts.
 *
 * The ownership change must not run the Account actions registered with the
 * Trigger Actions Framework (they are expensive), so the whole Account sObject is
 * bypassed with the transaction-level TriggerBase bypass for the duration of the
 * change. The Contact update is untouched, so all Contact trigger actions run
 * normally. The Account bypass is always removed before the method exits -
 * including when the DML fails - so Account automation behaves normally for the
 * rest of the transaction.
 */
public with sharing class AccountOwnershipService {
    /**
     * Sets OwnerId = newOwnerId on the given Accounts and on every Contact whose
     * AccountId is one of accountIds.
     *
     * Bulk-safe: one SOQL query and at most two all-or-none DML statements are
     * used whatever the volume. DML runs all-or-none and no exception is caught,
     * so failures propagate to the caller unchanged.
     *
     * @param accountIds Ids of the Accounts to reassign (up to 200 per call).
     * @param newOwnerId Id of the new owner for the Accounts and their Contacts.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        Set<Id> idsToReassign = accountIds == null ? new Set<Id>() : accountIds;

        // Field-only in-memory updates: no SOQL needed to change the Accounts.
        List<Account> accountsToUpdate = new List<Account>();
        List<Contact> contactsToUpdate = new List<Contact>();

        if (!idsToReassign.isEmpty()) {
            for (Id accountId : idsToReassign) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }

            for (Contact contactRecord : [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :idsToReassign
            ]) {
                contactsToUpdate.add(new Contact(Id = contactRecord.Id, OwnerId = newOwnerId));
            }
        }

        // Bypass every Trigger Actions Framework action for the Account sObject.
        TriggerBase.bypass(Account.SObjectType);
        try {
            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Restore Account automation even if the DML above threw.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
