/**
 * Trigger Action (after insert / after update on Opportunity) that records the Ids of the
 * Opportunities which must be pushed to the ERP.
 *
 * This class only accumulates Ids into the transaction-local buffer owned by
 * OpportunityErpSyncFinalizer. The Trigger Actions Framework invokes every registered DML finalizer
 * at the end of every DML operation it handles - after the trigger has run for all chunks of that
 * operation - so a single insert of 250 Opportunities (200 + 50 trigger chunks) still results in
 * exactly one OpportunityErpSyncJob containing all 250 Ids.
 *
 * Enqueueing the job from here would create one job per trigger chunk, and finalizers may not
 * perform DML, so the state is kept in static memory and is never persisted.
 */
public with sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate
{
    private static final String STAGE_NAME_FIELD = 'StageName';

    /**
     * Every inserted Opportunity has to be pushed to the ERP.
     */
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> opportunityIds = new Set<Id>();
        if (triggerNew != null) {
            for (SObject newRecord : triggerNew) {
                if (newRecord != null && newRecord.Id != null) {
                    opportunityIds.add(newRecord.Id);
                }
            }
        }
        OpportunityErpSyncFinalizer.collectIds(opportunityIds);
    }

    /**
     * Only Opportunities whose StageName changed have to be pushed to the ERP again.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> opportunityIds = new Set<Id>();
        if (triggerNew != null) {
            for (Integer index = 0; index < triggerNew.size(); index++) {
                SObject newRecord = triggerNew[index];
                SObject oldRecord = (triggerOld != null && triggerOld.size() > index)
                    ? triggerOld[index]
                    : null;
                if (
                    newRecord != null &&
                    newRecord.Id != null &&
                    oldRecord != null &&
                    hasStageNameChanged(newRecord, oldRecord)
                ) {
                    opportunityIds.add(newRecord.Id);
                }
            }
        }
        OpportunityErpSyncFinalizer.collectIds(opportunityIds);
    }

    private static Boolean hasStageNameChanged(SObject newRecord, SObject oldRecord) {
        String newStageName = (String) newRecord.get(STAGE_NAME_FIELD);
        String oldStageName = (String) oldRecord.get(STAGE_NAME_FIELD);
        return newStageName != oldStageName;
    }
}
