 *
 * The Trigger Actions Framework calls every registered finalizer at the end of every DML operation
 * it handles, whatever the sObject type of that operation. This class therefore stays completely
 * sObject-agnostic: it drains the buffer of Ids filled by TA_Opportunity_CollectForErpSync during
 * the operation and enqueues exactly one OpportunityErpSyncJob when - and only when - that buffer
 * is not empty. Draining the buffer guarantees one job per DML statement (two DML statements in one
 * transaction produce two jobs, each with its own records), while the buffer accumulating across
 * trigger chunks guarantees a single job for a single large DML statement.
 *
 * Finalizers must not perform DML, so the buffer is static transaction state only; no custom
 * object or custom metadata is written.
 */
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer
{
    @TestVisible
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    /**
     * Adds the given Opportunity Ids to the buffer of the DML operation currently being processed.
     * Bulk safe and side-effect free: no DML and no queueable is executed here.
     */
    public static void collectIds(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }
        opportunityIdsToSync.addAll(opportunityIds);
    }

    /**
     * Runs at the end of every DML operation. Enqueues at most one OpportunityErpSyncJob and resets
     * the buffer so the next DML operation in the same transaction starts from a clean state.
     */
    public void execute(FinalizerHandler.Context context) {
        if (opportunityIdsToSync.isEmpty()) {
            return;
        }
        Set<Id> idsToSync = new Set<Id>(opportunityIdsToSync);
        opportunityIdsToSync.clear();
        System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
    }
}
