/**
 * DML-less, SOQL-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Trigger Actions Framework best practice: exercise a trigger action by calling the action's
 * context method directly with in-memory records instead of inserting and updating data.
 * Every record is given an Id from TriggerTestUtility.getFakeId(...) and errors are asserted
 * with the SObject error API (hasErrors()/getErrors()).
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static Opportunity newOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    private static void runBeforeUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
    }

    private static void assertNoErrors(Opportunity record, String label) {
        System.assertEquals(
            false,
            record.hasErrors(),
            label + ' must not be flagged with an error.'
        );
        System.assertEquals(
            0,
            record.getErrors().size(),
            label + ' must not carry any errors.'
        );
    }

    private static void assertSingleGuardError(Opportunity record, String label) {
        System.assertEquals(
            true,
            record.hasErrors(),
            label + ' must be flagged with an error.'
        );
        System.assertEquals(
            1,
            record.getErrors().size(),
            label + ' must carry exactly one error.'
        );
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            record.getErrors()[0].getMessage(),
            label + ' must carry the guard error message.'
        );
    }

    // ------------------------------------------------------------------
    // Tests
    // ------------------------------------------------------------------

    @IsTest
    private static void rejectsReductionOfMoreThanHalf() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = newOpportunity(recordId, 1000);
        Opportunity newRecord = newOpportunity(recordId, 499);

        runBeforeUpdate(new List<Opportunity>{ newRecord }, new List<Opportunity>{ oldRecord });

        assertSingleGuardError(newRecord, 'The 1000 -> 499 record');
        assertNoErrors(oldRecord, 'The triggerOld record of the 1000 -> 499 update');
    }

    @IsTest
    private static void acceptsReductionOfExactlyHalf() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = newOpportunity(recordId, 1000);
        Opportunity newRecord = newOpportunity(recordId, 500);

        runBeforeUpdate(new List<Opportunity>{ newRecord }, new List<Opportunity>{ oldRecord });

        assertNoErrors(newRecord, 'The 1000 -> 500 record');
    }

    @IsTest
    private static void acceptsIncrease() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = newOpportunity(recordId, 1000);
        Opportunity newRecord = newOpportunity(recordId, 1500);

        runBeforeUpdate(new List<Opportunity>{ newRecord }, new List<Opportunity>{ oldRecord });

        assertNoErrors(newRecord, 'The 1000 -> 1500 record');
    }

    @IsTest
    private static void acceptsUpdateWhenPreviousAmountWasNull() {
        Id recordId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = new Opportunity(Id = recordId);
        Opportunity newRecord = newOpportunity(recordId, 1000);

        System.assertEquals(
            null,
            oldRecord.Amount,
            'Precondition: the previous Amount must be null.'
        );

        // This call must complete without throwing (e.g. no NullPointerException).
        runBeforeUpdate(new List<Opportunity>{ newRecord }, new List<Opportunity>{ oldRecord });

        assertNoErrors(newRecord, 'The null -> 1000 record');
        assertNoErrors(oldRecord, 'The triggerOld record of the null -> 1000 update');
    }

    @IsTest
    private static void flagsOnlyTheViolatingRecordsOfABulkCall() {
        Id overReducedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id exactHalfId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increasedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id nullOldAmountId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id smallOverReducedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity overReducedOld = newOpportunity(overReducedId, 1000);
        Opportunity overReducedNew = newOpportunity(overReducedId, 400);

        Opportunity exactHalfOld = newOpportunity(exactHalfId, 1000);
        Opportunity exactHalfNew = newOpportunity(exactHalfId, 500);

        Opportunity increasedOld = newOpportunity(increasedId, 1000);
        Opportunity increasedNew = newOpportunity(increasedId, 2500);

        Opportunity nullOldAmountOld = new Opportunity(Id = nullOldAmountId);
        Opportunity nullOldAmountNew = newOpportunity(nullOldAmountId, 750);

        Opportunity smallOverReducedOld = newOpportunity(smallOverReducedId, 200);
        Opportunity smallOverReducedNew = newOpportunity(smallOverReducedId, 90);

        List<Opportunity> triggerNew = new List<Opportunity>{
            overReducedNew,
            exactHalfNew,
            increasedNew,
            nullOldAmountNew,
            smallOverReducedNew
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            overReducedOld,
            exactHalfOld,
            increasedOld,
            nullOldAmountOld,
            smallOverReducedOld
        };

        runBeforeUpdate(triggerNew, triggerOld);

        // Only the two records that break the rule are flagged, and each exactly once.
        assertSingleGuardError(overReducedNew, 'The 1000 -> 400 record');
        assertSingleGuardError(smallOverReducedNew, 'The 200 -> 90 record');

        // The compliant records carry no error at all.
        assertNoErrors(exactHalfNew, 'The 1000 -> 500 record');
        assertNoErrors(increasedNew, 'The 1000 -> 2500 record');
        assertNoErrors(nullOldAmountNew, 'The null -> 750 record');

        Integer flaggedRecords = 0;
        for (Opportunity record : triggerNew) {
            if (record.hasErrors()) {
                flaggedRecords++;
            }
        }
        System.assertEquals(
            2,
            flaggedRecords,
            'Exactly the two over-reduced records must be flagged in the bulk call.'
        );

        // triggerNew and triggerOld stay aligned, and the old records are never touched.
        System.assertEquals(
            triggerOld.size(),
            triggerNew.size(),
            'Every triggerNew record must have a matching triggerOld record.'
        );
        for (Opportunity record : triggerOld) {
            assertNoErrors(record, 'A triggerOld record');
        }
    }
}
