/**
 * Trigger Actions Framework (TAF) action.
 *
 * Rule: two Contacts on the same Account may not share an Email address. Email
 * addresses are compared case-insensitively. Contacts without an Account or
 * without an Email are not checked.
 *
 * Behaviour for one DML statement:
 *   - On update only Contacts whose Email or AccountId changed are validated, so
 *     pre-existing (legacy) duplicates never block unrelated edits.
 *   - A Contact is never compared against itself.
 *   - Every record that breaks the rule receives a record-level addError with
 *     ERROR_MESSAGE; all other records of the same save are left untouched, so
 *     partial saves work.
 *   - When several records of the same save want the same Account/Email
 *     combination, the first record in the list is accepted and each later one
 *     is rejected.
 *   - The action executes a single SOQL statement per trigger execution.
 *
 * Registered with Trigger_Action__mdt:
 *   TA_Contact_PreventDuplicateEmail_BI -> before insert, Order__c = 10
 *   TA_Contact_PreventDuplicateEmail_BU -> before update, Order__c = 10
 *
 * Declared without sharing: this is a data-integrity rule and must see every
 * Contact on the account regardless of what the running user happens to share.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    private static final String KEY_SEPARATOR = '|';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate(triggerNew, triggerOld);
    }

    // ---------------------------------------------------------------------
    // Implementation
    // ---------------------------------------------------------------------

    private static void validate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = toContacts(triggerNew);
        List<Contact> oldContacts = (triggerOld == null) ? null : toContacts(triggerOld);

        // 1. Collect the account/email combinations that have to be validated.
        Map<Integer, String> indexToKey = new Map<Integer, String>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newContact = newContacts[i];
            if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }
            if (oldContacts != null && !hasRelevantChange(oldContacts[i], newContact)) {
                continue;
            }
            indexToKey.put(i, buildKey(newContact.AccountId, newContact.Email));
            accountIds.add(newContact.AccountId);
            emails.add(newContact.Email);
        }

        if (indexToKey.isEmpty()) {
            return;
        }

        // 2. One SOQL statement for the whole trigger execution: every Contact that
        //    already owns one of those combinations. SOQL compares strings
        //    case-insensitively, so duplicates that only differ in case are returned too.
        Map<String, Set<Id>> keyToExistingIds = queryExistingKeys(accountIds, emails);

        // 3. Walk the list in order: the first record to claim a combination wins.
        Set<String> claimedKeys = new Set<String>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            String key = indexToKey.get(i);
            if (key == null) {
                continue;
            }
            Contact newContact = newContacts[i];
            if (isDuplicate(key, newContact.Id, keyToExistingIds, claimedKeys)) {
                newContact.addError(ERROR_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }

    private static Map<String, Set<Id>> queryExistingKeys(Set<Id> accountIds, Set<String> emails) {
        Map<String, Set<Id>> keyToExistingIds = new Map<String, Set<Id>>();
        for (Contact existingContact : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails
        ]) {
            if (existingContact.AccountId == null || String.isBlank(existingContact.Email)) {
                continue;
            }
            String key = buildKey(existingContact.AccountId, existingContact.Email);
            Set<Id> idsForKey = keyToExistingIds.get(key);
            if (idsForKey == null) {
                idsForKey = new Set<Id>();
                keyToExistingIds.put(key, idsForKey);
            }
            idsForKey.add(existingContact.Id);
        }
        return keyToExistingIds;
    }

    private static Boolean isDuplicate(
        String key,
        Id contactId,
        Map<String, Set<Id>> keyToExistingIds,
        Set<String> claimedKeys
    ) {
        Set<Id> existingIds = keyToExistingIds.get(key);
        if (existingIds != null) {
            for (Id existingId : existingIds) {
                // A Contact never conflicts with itself.
                if (existingId != contactId) {
                    return true;
                }
            }
        }
        // Another record earlier in this save already owns this combination.
        return claimedKeys.contains(key);
    }

    private static Boolean hasRelevantChange(Contact oldContact, Contact newContact) {
        return emailChanged(oldContact, newContact) || accountChanged(oldContact, newContact);
    }

    private static Boolean emailChanged(Contact oldContact, Contact newContact) {
        String oldEmail = oldContact.Email;
        String newEmail = newContact.Email;
        if (oldEmail == null) {
            return newEmail != null;
        }
        // String.equals() is case-sensitive; Apex's == on Strings is not.
        return !oldEmail.equals(newEmail);
    }

    private static Boolean accountChanged(Contact oldContact, Contact newContact) {
        return oldContact.AccountId != newContact.AccountId;
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + KEY_SEPARATOR + email.toLowerCase();
    }

    private static List<Contact> toContacts(List<SObject> records) {
        List<Contact> contacts = new List<Contact>();
        for (SObject record : records) {
            contacts.add((Contact) record);
        }
        return contacts;
    }
}
