/**
 * Trigger Actions Framework action (0.3.4) that normalizes Lead contact
 * information during the before insert context, so the values are already
 * clean at first save.
 *
 *   Email      - trimmed and lower-cased (null is left null)
 *   Company    - trimmed
 *   LeadSource - defaults to 'Web' when blank; an existing value is kept
 *
 * Registered by the Trigger_Action__mdt record
 * TA_Lead_NormalizeContactInfo (Before_Insert__c = Lead, Order__c = 10).
 *
 * Pure in-memory field normalization: no SOQL, no DML, bulk-safe for up to
 * 200 records per trigger execution.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    public void beforeInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        for (Lead newLead : (List<Lead>) triggerNew) {
            if (newLead.Email != null) {
                newLead.Email = newLead.Email.trim().toLowerCase();
            }

            if (newLead.Company != null) {
                newLead.Company = newLead.Company.trim();
            }

            if (String.isBlank(newLead.LeadSource)) {
                newLead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }
}
