```apex
/**
 * Trigger Actions Framework (TAF) action for Case.
 *
 * Keeps Account.FB_Open_Case_Count__c equal to the number of that Account's Cases
 * with IsClosed = false. Registered in every after context in which a Case can
 * appear, disappear or move between Accounts: after insert, after update,
 * after delete and after undelete.
 *
 * How it works
 *  - The Account ids of both the new and the old version of every affected Case
 *    are collected, so a Case that is moved to another Account keeps both
 *    Accounts correct.
 *  - The open Case count is recalculated for all of those Accounts with one
 *    aggregate query. Recalculating (instead of incrementing) makes the action
 *    idempotent and safe whatever else runs in the same transaction.
 *  - The current values of the affected Accounts are read with one more query.
 *    Accounts that are already correct are not written at all (no useless DML
 *    rows, no pointless Account automation), and Accounts that were deleted in
 *    the same transaction - for example when Cases are deleted together with
 *    their Account - are skipped instead of failing with ENTITY_IS_DELETED.
 *  - The new value is written with a single DML statement. An Account with no
 *    open Cases is explicitly set to 0 rather than left blank.
 *
 * Cost per trigger execution: 2 SOQL queries and at most 1 DML statement, no
 * matter how many Cases (up to 200 per operation) are in the trigger context.
 * Cases without an Account are ignored.
 *
 * Declared without sharing on purpose: the roll-up must count every Case, not
 * only the Cases that happen to be visible to the running user.
 */
public without sharing class TA_Case_RollupOpenCount
    implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        rollupOpenCaseCounts(collectAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        rollupOpenCaseCounts(collectAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        rollupOpenCaseCounts(collectAccountIds(null, triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        rollupOpenCaseCounts(collectAccountIds(triggerNew, null));
    }

    private static Set<Id> collectAccountIds(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        addAccountIds(accountIds, triggerNew);
        addAccountIds(accountIds, triggerOld);
        return accountIds;
    }

    private static void addAccountIds(Set<Id> accountIds, List<SObject> records) {
        if (records == null) {
            return;
        }
        for (SObject record : records) {
            Id accountId = (Id) record.get('AccountId');
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
    }

    private static void rollupOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL 1 of 2: how many open Cases does each affected Account have right
        // now? Deleted Cases are excluded automatically, so after delete is safe.
        Map<Id, Integer> openCasesByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
            SELECT AccountId accountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCasesByAccountId.put(
                (Id) result.get('accountId'),
                (Integer) result.get('openCount')
            );
        }

        // SOQL 2 of 2: the current value of the roll-up field on the affected
        // Accounts (accounts deleted in this transaction are simply not returned).
        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Integer openCases = openCasesByAccountId.get(account.Id);
            if (openCases == null) {
                openCases = 0;
            }
            Decimal expectedCount = openCases;
            if (account.FB_Open_Case_Count__c != expectedCount) {
                accountsToUpdate.add(
                    new Account(
                        Id = account.Id,
                        FB_Open_Case_Count__c = expectedCount
                    )
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
