/**
 * Audit action for Finance: whenever an Opportunity's Amount changes on update, create one
 * completed Task ("Amount changed") on that Opportunity.
 *
 * Recursion handling: TA_Opportunity_RoundAmount (Order 20) updates the same opportunities again
 * in the same transaction, and that nested update re-runs every Opportunity action. Static state
 * lives for the whole transaction, so tracking the Ids already logged guarantees at most one audit
 * Task per opportunity per transaction - the rounding is treated as part of the user's original
 * change, not as a separate change.
 *
 * Bulk safety: a single Task insert per trigger execution, sized for 200 opportunities.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final String TASK_SUBJECT = 'Amount changed';
    private static final String TASK_STATUS = 'Completed';

    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (
            triggerNew == null ||
            triggerNew.isEmpty() ||
            triggerOld == null ||
            triggerOld.size() != triggerNew.size()
        ) {
            return;
        }

        List<Task> auditTasks = new List<Task>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];
            if (newOpp == null || oldOpp == null) {
                continue;
            }
            if (!amountChanged(newOpp.Amount, oldOpp.Amount)) {
                continue;
            }
            if (loggedOpportunityIds.contains(newOpp.Id)) {
                continue;
            }
            loggedOpportunityIds.add(newOpp.Id);
            auditTasks.add(
                new Task(
                    WhatId = newOpp.Id,
                    Subject = TASK_SUBJECT,
                    Status = TASK_STATUS
                )
            );
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }

    private static Boolean amountChanged(Decimal newAmount, Decimal oldAmount) {
        if (newAmount == null && oldAmount == null) {
            return false;
        }
        return newAmount == null || oldAmount == null || newAmount != oldAmount;
    }
}
