/**
 * Trigger scoped data access shared by the Contact before insert trigger actions.
 *
 * The nested Service class is registered as a Trigger Action (Order__c = 1) and runs
 * before the behavioural actions. It populates accountsById with exactly one SOQL
 * query per trigger execution, so no action ever has to query Accounts itself.
 */
public inherited sharing class TA_Contact_Queries {
    /** Parent Accounts of the records of the current trigger execution, keyed by Id. */
    public Map<Id, Account> accountsById;

    private static TA_Contact_Queries instance;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    /**
     * @return the transaction scoped singleton instance.
     */
    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger Action that loads the parent Accounts for the records of the current
     * trigger execution. The map is replaced - never appended to - on every execution,
     * because later DML in the same transaction can involve other Accounts.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact contact : (List<Contact>) triggerNew) {
                if (contact.AccountId != null) {
                    accountIds.add(contact.AccountId);
                }
            }

            // One query for the whole trigger execution; shared with every other action.
            TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        AccountSource,
                        BillingCity,
                        BillingCountry,
                        BillingPostalCode,
                        BillingStreet
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
    }
}
