/**
 * Before insert: a new Contact that has a parent Account and a blank LeadSource
 * defaults its LeadSource from the Account's AccountSource.
 */
public inherited sharing class TA_Contact_DefaultLeadSource
    implements TriggerAction.BeforeInsert
{
    public void beforeInsert(List<SObject> triggerNew) {
        // Loaded once per trigger execution by TA_Contact_Queries.Service.
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact contact : (List<Contact>) triggerNew) {
            if (contact.AccountId == null || String.isNotBlank(contact.LeadSource)) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            contact.LeadSource = account.AccountSource;
        }
    }
}
